"""Exact-model setting frames generated by each appliance's vendor codec."""
import pytest

from midea_ac_lan.ble.appliances import HEATER, HOOD, setting


@pytest.mark.parametrize(("profile", "key", "value", "wire"), [
    (HOOD, "light", True, "aa12b6000000000000021101020201ffffff22"),
    (HOOD, "light", False, "aa12b6000000000000021101020200ffffff23"),
    (HEATER, "beep", True, "aa1ee3000000000000021415010000000000000000000000000000000001d2"),
    (HEATER, "beep", False, "aa1ee3000000000000021415000000000000000000000000000000000000d4"),
])
def test_setting(profile, key, value, wire):
    assert setting(profile, key, value) == bytes.fromhex(wire)


@pytest.mark.parametrize("profile", [HOOD, HEATER])
def test_power_is_not_a_ble_setting(profile):
    with pytest.raises(ValueError, match="Unsupported"):
        setting(profile, "power", True)
